package dev.hryshyn.remanence.ui.collage

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * T151 stage-3 differential: frozen V5 **resolve order**, **complete-safe
 * `assignPhotos` matching** and the **DECISIONS candidate cap**.
 *
 * Expected data in `src/test/resources/collage/v5_resolve_reference.txt` is
 * generated by `tasks/T151/evidence/ref_resolve.js`, which loads the
 * authoritative freeze runtime + `app/generator-adapter.js` unmodified and runs
 * the frozen `assignPhotos`/`validate`/`resolve` over the T153 real-feature
 * inputs, in both `lockOrder:true` (source-order) and default (complete-safe)
 * modes, plus the playground `resolveCandidates` cap. The raw assignment matrix
 * is self-checked inside the generator against the frozen `assignPhotos`.
 */
class FrozenResolveTest {

    private val stub = FrozenGrammarPlans.LINE_HEIGHT_STUB
    private val costTol = 1e-4

    private data class PhotoRef(val id: String, val width: Double, val height: Double, val hasFace: Boolean)

    private data class BranchExp(
        val failure: String?,
        val mode: String?,
        val order: List<String>,
        val visits: Int,
        val cost: Double?,
        val validateOk: Boolean,
    )

    private data class ResolveExp(val status: String, val branch: String?, val mode: String?, val order: List<String>)

    private class GrammarRef(val gid: Int, val applicable: Boolean) {
        val matrices = HashMap<Int, List<List<Double?>>>()
        val branches = HashMap<Pair<String, Int>, BranchExp>()
        val resolves = HashMap<String, ResolveExp>()
        val cap = ArrayList<String>()
    }

    private class FixtureRef(val id: String, val note: Boolean, val music: Boolean) {
        val photos = LinkedHashMap<String, PhotoRef>()
        var grammar: GrammarRef? = null
        val grammars = ArrayList<GrammarRef>()
        val policy = ArrayList<Pair<Int, String>>()
    }

    private fun fixture(): List<FixtureRef> {
        val text = requireNotNull(javaClass.getResource("/collage/v5_resolve_reference.txt")) {
            "missing resolve reference fixture"
        }.readText()
        val fixtures = ArrayList<FixtureRef>()
        var current: FixtureRef? = null
        for (raw in text.lineSequence()) {
            if (raw.isBlank() || raw.startsWith("#")) continue
            val f = raw.trimEnd('\r').split('\t')
            when (f[0]) {
                "FIXTURE" -> {
                    current = FixtureRef(f[1], f[3] == "1", f[4] == "1")
                    fixtures += current
                }
                "PHOTO" -> {
                    val fx = requireNotNull(current)
                    fx.photos[f[1]] = PhotoRef(f[1], f[2].toDouble(), f[3].toDouble(), f[4] == "1")
                }
                "GRAMMAR" -> {
                    val fx = requireNotNull(current)
                    val g = GrammarRef(f[1].toInt(), f[2] == "1")
                    fx.grammar = g
                    fx.grammars += g
                }
                "MATRIX" -> {
                    val g = requireNotNull(requireNotNull(current).grammar)
                    val n = requireNotNull(current).photos.size
                    val matrix = if (f.getOrElse(2) { "" }.isEmpty()) {
                        emptyList()
                    } else {
                        f[2].split(';').map { row ->
                            val cells = MutableList<Double?>(n) { null }
                            if (row.isNotEmpty()) {
                                for (entry in row.split('|')) {
                                    val parts = entry.split(',')
                                    val j = parts[0].toInt()
                                    if (parts[1] == "1") cells[j] = parts[2].toDouble()
                                }
                            }
                            cells
                        }
                    }
                    g.matrices[f[1].toInt()] = matrix
                }
                "BRANCH" -> {
                    val g = requireNotNull(requireNotNull(current).grammar)
                    g.branches[f[1] to f[2].toInt()] = BranchExp(
                        failure = f[4].takeIf { it != "-" },
                        mode = f[5].takeIf { it.isNotEmpty() && it != "-" },
                        order = if (f[6] == "-") emptyList() else f[6].split(','),
                        visits = f[7].toInt(),
                        cost = f[8].takeIf { it != "-" }?.toDouble(),
                        validateOk = f[9] == "1",
                    )
                }
                "RESOLVE" -> {
                    val g = requireNotNull(requireNotNull(current).grammar)
                    g.resolves[f[1]] = ResolveExp(
                        status = f[2],
                        branch = f[3].takeIf { it != "-" },
                        mode = f[4].takeIf { it != "-" },
                        order = if (f[5] == "-") emptyList() else f[5].split(','),
                    )
                }
                "CAP" -> {
                    val g = requireNotNull(requireNotNull(current).grammar)
                    for (i in 3 until f.size) g.cap += f[i].substringBefore('|')
                }
                "POLICY" -> {
                    val fx = requireNotNull(current)
                    for (i in 1 until f.size) {
                        val gid = f[i].substringBefore(':').toInt()
                        val branch = f[i].substringAfter(':')
                        fx.policy += gid to branch
                    }
                }
            }
        }
        return fixtures
    }

    @Test
    fun assignmentValidateAndResolveMatchFrozenReference() {
        var comparedBranches = 0
        var comparedResolves = 0
        for (fx in fixture()) {
            val photos = fx.photos.values.map { FrozenResolve.Photo(it.id, it.width, it.height) }
            val inputPhotos = fx.photos.values.map {
                FrozenGrammarPlans.Photo(it.id, it.width, it.height, it.hasFace)
            }
            val d = FrozenGrammarPlans.Input(
                id = fx.id,
                sender = "T151",
                photos = inputPhotos,
                note = if (fx.note) "note" else null,
                music = if (fx.music) FrozenGrammarPlans.MusicInput(artwork = false) else null,
            )
            val capBuckets = ArrayList<Pair<Int, List<String>>>()
            for (g in fx.grammars) {
                if (!g.applicable) continue
                val def = FrozenGrammarPlans.def(g.gid)
                val plans = FrozenGrammarPlans.plans(d, def, FrozenGrammarPlans.noteState(d, def, stub), stub)
                val matrices = plans.indices.map { index ->
                    requireNotNull(g.matrices[index]) { "missing MATRIX ${fx.id} g${g.gid} #$index" }
                }
                for (tag in listOf("lock", "safe")) {
                    val lock = tag == "lock"
                    for (i in plans.indices) {
                        val key = tag to i
                        val exp = requireNotNull(g.branches[key]) { "missing BRANCH ${fx.id} g${g.gid} $tag #$i" }
                        val act = FrozenResolve.assign(plans[i], photos, matrices[i], lock)
                        val label = "${fx.id} g${g.gid} $tag #$i ${plans[i].branch}"
                        assertEquals("failure ($label)", exp.failure, act.failure)
                        assertEquals("mode ($label)", exp.mode, act.mode)
                        assertEquals("order ($label)", exp.order, act.compositionOrder)
                        assertEquals("visits ($label)", exp.visits, act.feasibleAssignments)
                        if (exp.cost == null) {
                            assertEquals("cost null ($label)", null, act.cost)
                        } else {
                            assertNotNull("cost present ($label)", act.cost)
                            assertTrue(
                                "cost ($label) expected=${exp.cost} actual=${act.cost}",
                                Math.abs(exp.cost - requireNotNull(act.cost)) <= costTol,
                            )
                        }
                        val validateOk = if (act.failure != null) false else FrozenResolve.validate(plans[i])
                        assertEquals("validateOk ($label)", exp.validateOk, validateOk)
                        comparedBranches++
                    }
                    val actual = FrozenResolve.resolve(plans, photos, matrices, lock)
                    val expected = requireNotNull(g.resolves[tag]) { "missing RESOLVE ${fx.id} g${g.gid} $tag" }
                    val rlabel = "${fx.id} g${g.gid} $tag resolve"
                    assertEquals("status ($rlabel)", expected.status, actual.status)
                    assertEquals("branch ($rlabel)", expected.branch, actual.branch)
                    assertEquals("mode ($rlabel)", expected.mode, actual.assignmentMode)
                    assertEquals("order ($rlabel)", expected.order, actual.compositionOrder)
                    comparedResolves++
                }
                capBuckets += g.gid to g.cap
            }
            val ranked = FrozenCandidatePolicy.rank(capBuckets)
            assertEquals(
                "DECISIONS cap (${fx.id})",
                fx.policy,
                ranked.map { it.grammarId to it.branch },
            )
        }
        assertTrue("differential must compare a substantial branch set, got $comparedBranches", comparedBranches > 1000)
        assertTrue("differential must compare resolve per grammar/mode, got $comparedResolves", comparedResolves > 100)
    }

    /**
     * Headline probe: for the T034 triple and the first-3 reject case the frozen
     * **complete-safe** resolver lands on `editorial-1+2-equal-1.3`, while the
     * source-order (`lockOrder`) resolver lands on `.3` (f2) / `-1` (f1). This is
     * the exact case that must not be replaced by an unsafe source-order fallback.
     */
    @Test
    fun completeSafeMatchingRescuesBranchesSourceOrderCannot() {
        val byId = fixture().associateBy { it.id }
        val f1 = requireNotNull(byId["f1_p3_t034_triple_no_note_no_music"])
        val g5f1 = requireNotNull(f1.grammars.firstOrNull { it.gid == 5 })
        assertEquals("editorial-1+2-equal-1", requireNotNull(g5f1.resolves["lock"]).branch)
        assertEquals("editorial-1+2-equal-1.3", requireNotNull(g5f1.resolves["safe"]).branch)

        val f2 = requireNotNull(byId["f2_p3_first3_reject_case"])
        val g5f2 = requireNotNull(f2.grammars.firstOrNull { it.gid == 5 })
        assertEquals("editorial-1+2-equal-1.3", requireNotNull(g5f2.resolves["lock"]).branch)
        assertEquals("editorial-1+2-equal-1.3", requireNotNull(g5f2.resolves["safe"]).branch)
    }

    @Test
    fun candidatePolicyRoundRobinsGrammarBreadthThenSecondLayout() {
        val buckets = listOf(
            5 to listOf("a1", "a2"),
            6 to listOf("b1"),
            11 to listOf("c1", "c2"),
        )
        val ranked = FrozenCandidatePolicy.rank(buckets)
        assertEquals(
            listOf(5 to "a1", 6 to "b1", 11 to "c1", 5 to "a2", 11 to "c2"),
            ranked.map { it.grammarId to it.branch },
        )
        // Cap: never more than two per grammar, never more than twelve total.
        val many = (1..20).map { gid -> gid to listOf("x1", "x2", "x3") }
        val capped = FrozenCandidatePolicy.rank(many)
        assertEquals(FrozenCandidatePolicy.MAX_TOTAL, capped.size)
        capped.groupBy { it.grammarId }.forEach { (_, v) -> assertTrue(v.size <= 2) }
    }
}
